/// The Soul / system-prompt markdown in full.
/// Whether the Soul came from a sidecar .soul.md (vs inline).
/// The raw parsed config (for the editor to bind to form fields).
/// Read a built-in [Role]'s trait methods back into a config struct, so the
/// UI/API can present built-ins uniformly alongside user roles.
/// 
/// (Ports the private profession_to_config helper from roles.rs.)
fn profession_to_config(prof: Box<dyn Role>) -> RoleConfig {
    let t = prof.allowed_tools();
    let at = prof.allowed_tiers();
    let s = prof.skills();
    let mut tools: Option<Vec<String>> = None;
    if t.is_empty() == false {
        tools = Some(t)
    }
    let mut tiers: Option<Vec<ModelTier>> = None;
    if at.is_empty() == false {
        tiers = Some(at)
    }
    let mut skills: Option<Vec<String>> = None;
    if s.is_empty() == false {
        skills = Some(s)
    }
    return RoleConfig { name: Some(prof.name()), description: None, model: Some(prof.model()), model_tier: Some(prof.model_tier()), temperature: Some(prof.temperature()), max_turns: Some(prof.max_turns()), system_prompt: Some(prof.system_prompt()), system_prompt_append: None, tools: tools, tools_append: None, inherit: None, memory_limit: prof.memory_limit(), allowed_tiers: tiers, skills: skills, token_budget: prof.token_budget(), soul_file: None };
}

